/**
 * Learning record export copy (English). shared/learning-export.ts builds
 * the Markdown from it on the server and for the client-side demo export.
 */
import { formatters } from "./locale.js";
import { product } from "../product.js";

const fmt = formatters("en");

const messages = {
  title: ({ title }: { title: string }) => `# Learning record: ${title}`,
  disclaimer:
    "> The explanations, chat answers and reviews in this record were generated by agents and may be wrong; the parts marked as yours are your own words. Verify the code and the conclusions yourself.",
  repository: ({ fullName }: { fullName: string }) =>
    `- Repository: ${fullName}`,
  branch: ({ branch, baseBranch }: { branch: string; baseBranch: string }) =>
    `- Branch: ${branch} → ${baseBranch}`,
  createdAt: ({ createdAt }: { createdAt: string }) =>
    `- Created: ${createdAt}`,
  status: ({ status }: { status: string }) => `- Status: ${status}`,
  sections: {
    task: "Task",
    plan: "Team plan",
    explanations: "File explanations",
    conversations: "Questions and answers",
    pullRequest: "Pull request",
    usage: "Agent usage",
    notes: "Your notes",
    explainBack: "Explain it back",
    roads: "Road choices",
    forecast: "Your forecast",
    feedbackTags: "Maintainer feedback you tagged",
    overrides: "Checks you overrode, with your reasons",
  },
  noPullRequest: "No pull request has been opened yet.",
  noExplanations: "No explanations have been generated yet.",
  explanationStatus: ({ status }: { status: string }) =>
    `Explanation status: ${status}`,
  explanationStatusWithError: ({
    status,
    error,
  }: {
    status: string;
    error: string;
  }) => `Explanation status: ${status} (${error})`,
  example: ({
    scenario,
    before,
    after,
  }: {
    scenario: string;
    before: string;
    after: string;
  }) =>
    `**In everyday terms**\n\n- Scenario: ${scenario}\n- Before: ${before}\n- After: ${after}`,
  /** Labels of the explanation card fields, in the order they are exported. */
  fields: {
    summary: "What changed",
    reason: "Why",
    concept: "Concept",
    tip: "Review tip",
    alternatives: "Other approaches",
    lookup: "Look up",
  },
  selfCheck: ({ question, answer }: { question: string; answer: string }) =>
    `**Check yourself**\n\nQuestion: ${question}\n\nAnswer: ${answer}`,
  noConversations: "No questions and answers were recorded.",
  you: "You",
  assistant: "Learning assistant",
  turn: ({ author }: { author: string }) => `**${author}:**`,
  /** A turn asked or answered about an earlier version of the file. */
  staleTurn: ({ author }: { author: string }) =>
    `**${author} (about an earlier version):**`,
  noUsage: "No usage was recorded.",
  calls: ({
    calls,
    completed,
    failed,
  }: {
    calls: number;
    completed: number;
    failed: number;
  }) =>
    `- Agent calls: ${fmt.number(calls)} (${fmt.number(completed)} completed, ${fmt.number(failed)} failed)`,
  measured: ({ measured, calls }: { measured: number; calls: number }) =>
    `- Usage reported: ${fmt.number(measured)} of ${fmt.number(calls)} calls`,
  inputTokens: ({ input, cached }: { input: number; cached: number }) =>
    `- Input tokens: ${fmt.number(input)} (including ${fmt.number(cached)} read from cache)`,
  outputTokens: ({ output }: { output: number }) =>
    `- Output tokens: ${fmt.number(output)}`,
  duration: ({ seconds }: { seconds: number }) =>
    `- Agent run time: ${fmt.number(seconds)} ${fmt.plural(seconds) === "one" ? "second" : "seconds"}`,
  mode: ({ mode, policyVersion }: { mode: string; policyVersion: string }) =>
    `- Ponytail mode: ${mode} (${policyVersion})`,
  unmeasured:
    "- Note: some calls did not report their usage. The token counts above add up only the reported calls; unreported usage is unknown, not zero.",
  checkOff: "Approved with the understanding check off.",
  summary: ({ summary }: { summary: string }) =>
    `**Your explanation**\n\n${summary}`,
  question: ({ question }: { question: string }) => `**Question:** ${question}`,
  answer: ({ answer, confidence }: { answer: string; confidence: string }) =>
    `**Your answer** (${confidence}): ${answer}`,
  dontKnow: ({ confidence }: { confidence: string }) =>
    `**Your answer** (${confidence}): I don't know`,
  grade: ({ grade }: { grade: string }) => `**Your grade:** ${grade}`,
  correction: ({ correction }: { correction: string }) =>
    `**What you had wrong:** ${correction}`,
  passed: ({ passedAt, questions, misses }: { passedAt: string; questions: number; misses: number }) =>
    `- Passed ${passedAt}: ${fmt.number(questions)} ${fmt.plural(questions) === "one" ? "question" : "questions"}, ${fmt.number(misses)} missed`,
  roadGuess: ({ guess }: { guess: string }) =>
    `**How else it could be done (your guess):** ${guess}`,
  roadChoice: ({ choice }: { choice: string }) => `**Your choice:** ${choice}`,
  roadWhy: ({ why }: { why: string }) => `**Why:** ${why}`,
  forecastDimension: ({ dimension }: { dimension: string }) =>
    `**What the maintainer would question:** ${dimension}`,
  /** One tagged feedback item: its URL, then the tags. */
  tag: ({ url, facts }: { url: string; facts: string[] }) =>
    facts.length ? `- ${url}: ${fmt.list(facts, { type: "unit" })}` : `- ${url}`,
  sawItComing: "saw it coming",
  surprised: "surprised me",
  lesson: ({ lesson }: { lesson: string }) => `Lesson: ${lesson}`,
  override: ({ check, reason, at }: { check: string; reason: string; at: string }) =>
    `- ${check} (${at}): ${reason}`,
  confidences: { sure: "Sure", think: "Think so", guess: "Guessing" } as Record<string, string>,
  grades: { got: "Got it", partly: "Partly", missed: "Missed" } as Record<string, string>,
  roadChoices: {
    keep: "Keep this approach",
    switch: "Prefer the other",
    depends: "It depends",
  } as Record<string, string>,
  dimensions: {
    scope: "Scope",
    simplicity: "Simplicity",
    naming: "Naming",
    conventions: "Project conventions",
    tests: "Tests",
    risk: "Risk",
    description: "Description",
    worth: "Worth the review time",
  } as Record<string, string>,
  overrideChecks: {
    "issue-has-pr": "Someone else's pull request already closes the issue",
  } as Record<string, string>,
};

export default messages;

/**
 * A Learn-by-hand run's record (DESIGN v1.2 F13): facts and plain counts,
 * never a score. Its own export, so the browser's sample export (never a
 * Learn-by-hand run, DESIGN v1.2 §13) leaves it out of the bundle.
 */
export const byHand = {
  title: "Learn by hand",
  claim: `${product.name}'s agents had no write access and gave you no code for this change.`,
  withdrawn: `${product.name} saw an agent change files or run commands in this run, so it makes no Learn-by-hand claim for it.`,
  fitted: ({ kinds }: { kinds: string }) =>
    `Fitted to the project's rules when it started: the guide offered only ${kinds}.`,
  helps: ({ helps }: { helps: string }) => `- Help from the guide: ${helps}`,
  predictions: ({ right, judged, unsure }: { right: number; judged: number; unsure: number }) =>
    `- Your first prediction after each change was right ${right} of ${judged} times; Not sure ${unsure}`,
  removed: ({ count }: { count: number }) => `- ${product.name} removed code from ${count} answers before you saw them`,
  kinds: {
    explain: "explanations",
    answer: "answers",
    plan: "planning help",
    review: "reviews",
    test: "test help",
  } as Record<string, string>,
  notProof: `${product.name} can't see other tools you used, such as editor autocomplete. This record is for you; it isn't proof of who wrote the code.`,
};
